                                                    DBMS_OUTPUT.PUT_LINE('L_Result_0('||idx0||').CHECK_RESULTS('||idx1||').PARAMS_GUI('||idx2||').KEY_CD=' || to_char(L_Result_0(idx0).CHECK_RESULTS(idx1).PARAMS_GUI(idx2).KEY_CD));
                                                end if;
                                                DBMS_OUTPUT.PUT_LINE('-----------------------------------------End L_Result_0('||idx0||').CHECK_RESULTS('||idx1||').PARAMS_GUI-----------------------------------------');
                                            end loop;
                                        end if;
                                    else
                                        DBMS_OUTPUT.PUT_LINE('L_Result_0('||idx0||').CHECK_RESULTS('||idx1||').PARAMS_GUI is null');
                                    end if;
                                end if;
                                DBMS_OUTPUT.PUT_LINE('-----------------------------------------End L_Result_0('||idx0||').CHECK_RESULTS-----------------------------------------');
                            end loop;
                        end if;
                    else
                        DBMS_OUTPUT.PUT_LINE('L_Result_0('||idx0||').CHECK_RESULTS is null');
                    end if;
                    DBMS_OUTPUT.PUT_LINE('L_Result_0('||idx0||').VALIDATION_LEVEL=' || to_char(L_Result_0(idx0).VALIDATION_LEVEL));
                    DBMS_OUTPUT.PUT_LINE('L_Result_0('||idx0||').CLIENT_REF=' || to_char(L_Result_0(idx0).CLIENT_REF));

                -- submit:
                    -- DBMS_OUTPUT.PUT_LINE('L_Result_0('||idx0||').AUF_LNR=' || to_char(L_Result_0(idx0).AUF_LNR));                    

                end if;
                DBMS_OUTPUT.PUT_LINE('-----------------------------------------End L_Result_0-----------------------------------------');
            end loop;
        end if;
    else
        DBMS_OUTPUT.PUT_LINE('L_Result_0 is null');
    end if;

commit;

exception
    when others then
        dbms_output.put_line('sqlerrm = '|| sqlerrm);
        SRQMESS0.DumpMessages(); --Finnova spezifisches Log ausgeben
end;
